import java.util.Scanner;

public class Main {
    static final int MAXN = 510;
    static long[][] c = new long[MAXN][MAXN];
    static long[] f = new long[MAXN], g = new long[MAXN];
    static long[][] dp = new long[MAXN][MAXN], ways = new long[MAXN][MAXN];
    static long[][] dp2 = new long[MAXN][MAXN], ways2 = new long[MAXN][MAXN];
    static long[][] dp0 = new long[MAXN][MAXN], ways0 = new long[MAXN][MAXN];

    static long p;

    static void update_value(LongWrapper x, long y) {
        x.value = (x.value + y) % p;
    }

    static long binom(long x) {
        return (x * (x - 1) / 2) % p;
    }

    static class LongWrapper {
        long value;

        LongWrapper(long value) {
            this.value = value;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        p = sc.nextLong();

        for (int i = 0; i < MAXN; i++) {
            c[i][0] = 1;
        }
        for (int i = 1; i < MAXN; i++) {
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j - 1] + c[i - 1][j]) % p;
            }
        }

        f[0] = 0;
        g[0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                long val1 = c[i - 1][j - 1] * f[j - 1] % p * g[i - j] % p * (i + 1) % p;
                long val2 = c[i - 1][j - 1] * g[j - 1] % p * f[i - j] % p * (i + 1) % p;
                update_value(new LongWrapper(f[i]), val1 + val2 + (c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p) * ((binom(j) + binom(i - j + 1)) % p));
                update_value(new LongWrapper(g[i]), c[i - 1][j - 1] * g[j - 1] % p * g[i - j] % p * (i + 1) % p);
            }
        }

        for (int i = 0; i < MAXN; i++) {
            for (int j = 0; j < MAXN; j++) {
                dp[i][j] = 0;
                ways[i][j] = 0;
                dp0[i][j] = 0;
                ways0[i][j] = 0;
            }
        }

        dp[0][0] = 0;
        ways[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                for (int k = 0; k <= Math.min(j, m); k++) {
                    if (k == 0) {
                        dp0[i][j] = dp[j][0];
                        ways0[i][j] = ways[j][0];
                    }
                    // Initialize temporary wrappers for update_value
                    LongWrapper dp2_jk = new LongWrapper(dp2[j][k]);
                    LongWrapper ways2_jk = new LongWrapper(ways2[j][k]);
                    update_value(dp2_jk, dp[j][k]);
                    update_value(ways2_jk, ways[j][k]);
                    // Update dp2 and ways2
                    int rem = m - (j - k);
                    // For ways2[j+1][k+1]
                    LongWrapper ways2_j1_k1 = new LongWrapper(ways2[j + 1][k + 1]);
                    update_value(ways2_j1_k1, ways0[i - k][j - k] * c[rem][k + 1] % p * g[k + 1] % p);
                    ways2[j + 1][k + 1] = ways2_j1_k1.value;

                    // For dp2[j+1][k+1]
                    LongWrapper dp2_j1_k1 = new LongWrapper(dp2[j + 1][k + 1]);
                    long val_dp = (dp0[i - k][j - k] * c[rem][k + 1] % p * g[k + 1] % p + ways0[i - k][j - k] * c[rem][k + 1] % p * f[k + 1] % p) % p;
                    update_value(dp2_j1_k1, val_dp);
                    dp2[j + 1][k + 1] = dp2_j1_k1.value;
                }
            }
            // Copy back from dp2 and ways2 to dp and ways
            for (int j = 0; j < MAXN; j++) {
                for (int k = 0; k < MAXN; k++) {
                    dp[j][k] = dp2[j][k];
                    ways[j][k] = ways2[j][k];
                }
            }
        }

        long total = 0;
        for (int i = 0; i <= m; i++) {
            total = (total + dp[m][i]) % p;
        }
        System.out.println(total);
        sc.close();
    }
}

